mapper.select:


    t.is_deleted = 0

        AND t.trial_id like concat('%', #{trialId}, '%')


        AND t.batch_id = #{batchId}


        AND t.trial_name like concat('%', #{trialName}, '%')


        AND t.season = #{season}


order by t.create_time desc

select count(1) from trial_basic
where trial_name = #{trialName} and is_deleted = 0

    AND trial_id != #{trialId}

select trial_id, batch_id, trial_name, location_id, season, year, design_type, replications, crop_type, variety_code, variety_name from trial_basic where is_deleted = 0
AND batch_id = #{batchId}
order by create_time desc
